uid, 'Molarity is the number of moles of solute per liter of solvent.', FALSE, 0),('f94f970a-3831-41c6-8278-6c4664451565'::uuid, '64b032a2-0c0e-46c6-872d-c5f89c3acd6a'::uuid, 'Molarity is the number of moles of solute per liter of solution.', TRUE, 1),('f9f63c09-f329-40f1-8650-5d1132af3864'::uuid, '64b032a2-0c0e-46c6-872d-c5f89c3acd6a'::uuid, 'Molarity equals mass of solute per mass of solvent.', FALSE, 2),('653e8812-ee3f-4061-80a6-8e4f7e6cdf83'::uuid, '64b032a2-0c0e-46c6-872d-c5f89c3acd6a'::uuid, 'Molarity is the percent by mass.', FALSE, 3),('f711ab69-09a1-4278-8f8a-38779fd8ce2a'::uuid, 'bcf25a74-7ec9-4308-8cc5-42fcadb48b6f'::uuid, 'It contains more solute than the maximum.', FALSE, 0),('c36e6594-3cd1-433a-8013-b9f0fcd0c22c'::uuid, 'bcf25a74-7ec9-4308-8cc5-42fcadb48b6f'::uuid, 'It contains less solute than the maximum.', FALSE, 1),('d085c9fb-f76a-4e17-8e2e-a8af30ac44ba'::uuid, 'bcf25a74-7ec9-4308-8cc5-42fcadb48b6f'::uuid, 'It contains the maximum amount of solute that can dissolve at that temperature.', TRUE, 2),('9b4ef637-e997-4788-8740-a66e329ae135'::uuid, 'bcf25a74-7ec9-4308-8cc5-42fcadb48b6f'::uuid, 'It contains only solvent with no solute.', FALSE, 3),('00fcb9d1-a564-4314-8927-33497fc31254'::uuid, '0a950fe7-d645-4e09-875a-5ac710fc8013'::uuid, 'It contains more solute than the maximum.', FALSE, 0),('1f6522f7-d50f-406a-8e51-317be2614140'::uuid, '0a950fe7-d645-4e09-875a-5ac710fc8013'::uuid, 'It contains less solute than the maximum.', FALSE, 1),('6b1d8e7e-4575-438e-8577-ebb00ea90f05'::uuid, '0a950fe7-d645-4e09-875a-5ac710fc8013'::uuid, 'It contains the maximum amount of solute that can dissolve at that temperature.', TRUE, 2),('c9ec1726-3ce0-4c44-882b-f4b6ab0770a9'::uuid, '0a950fe7-d645-4e09-875a-5ac710fc8013'::uuid, 'Solubility keeps increasing with more solute.', FALSE, 3) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'Chemistry', 'Unit 3', 'Molarum Grade 10 — Chemistry IMPORTANT INORGANIC COMPOUNDS', 'Source-grounded Molarum Grade 10 Chemistry questions for IMPORTANT INORGANIC COMPOUNDS.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('a8fdf994-6c2a-4c19-896a-0e472d1bdad7'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which statement best describes a chemical change?', 'B) rusting of iron', 'Rusting involves formation of a new substance (iron oxide), unlike physical changes such as melting.', 0),('0fbf2e83-aec7-436d-8865-d64b7358cf29'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which oxide is an acidic oxide that forms an acid when dissolved in water?', 'SO3', 'Acidic oxides react with water to form acids; SO3 yields H2SO4.', 1),('12a91b2c-2e65-400f-859e-6ab2a43b6976'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which statement about acids is true?', 'They turn blue litmus red', 'Acids turn blue litmus red; they conduct electricity in aqueous solution; pH < 7.', 2),('5b679fd3-942f-4958-80ac-246355cced4f'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which of the following is true about bases?', 'They turn red litmus blue', 'Bases turn red litmus blue; may have bitter taste and slippery feel; they react with acids.', 3),('7b8785e6-9b35-4582-8e29-009292d258c6'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which statement about salts is correct?', 'Salts are formed by the neutralization of acids and bases', 'Salts are produced by neutralization; solubility depends on salt.', 4),('50c7e2ee-54d2-4f0e-8c65-774ce32e1087'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'true_false', 'Acids turn red litmus paper blue.', 'False', 'Acids turn blue litmus red rather than blue.', 5),('8d6f98c1-c989-4b0b-893d-2789d68f981c'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Define a chemical reaction in one sentence.', 'A chemical reaction is a process in which reactants are transformed into new substances (products).', 'Definition drawn from 3.1 Introduction.', 6),('d8ae02c1-da97-47af-8d7d-2d26e40461aa'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Name two evidences that a chemical change has occurred when an acid reacts with a base to form a salt and water.', 'Formation of a salt and a temperature change (exothermic or endothermic)', 'Neutralization forms salt and water; heat change is a common evidence.', 7),('b03e4c36-998a-4c5f-82f4-120834dda862'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Calculate the pH of a 0.01 M HCl solution.', '2.0', '[H+] = 0.01 M; pH = -log10(0.01) = 2.0', 8),('aabb9f1c-b811-4c49-8cae-35b11d7e1bb1'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'If 2.00 L of 1.50 M NaOH reacts completely with 0.50 L of 1.00 M H2SO4, how many grams of Na2SO4 are produced? Provide the method and final answer.', '35.51 g Na2SO4', 'Moles NaOH = 2.00 L × 1.50 M = 3.00 mol; Moles H2SO4 = 0.50 L × 1.00 M = 0.50 mol; Limiting reagent is H2SO4; Moles Na2SO4 produced = 0.25 mol; Na2SO4 molar mass ≈ 142.04 g/mol; Mass = 0.25 × 142.04 = 35.51 g.', 9),('b07ef478-01c0-496d-8bc8-8ecd460caf29'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which statement about oxides is correct?', 'An oxide is a compound formed when oxygen combines with another element.', 'Oxides are compounds in which oxygen is bonded to another element; many oxides are formed when oxygen combines with elements, not just oxygen itself.', 10),('109caf21-3e64-4d1b-8e51-80f12c6f2f76'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which substance is a base?', 'NaOH', 'NaOH is a strong base; it accepts protons and forms OH- in solution, unlike the acids or non-basic salts listed.', 11),('458946b5-441e-4b98-8577-05b66d1da3f5'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Define a salt and give one example.', 'Salt is a compound formed from the reaction of an acid with a base, containing positive and negative ions; Example: NaCl.', 'Salts are formed when acids neutralize bases; they consist of a cation from the base and an anion from the acid. Example: NaCl.', 12),('235eb277-ce6a-49d8-8789-435bd35fe5e5'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'true_false', 'Acids turn blue litmus paper red.', 'True', 'Acids acidify aqueous solutions and turn blue litmus red; bases turn red litmus blue.', 13),('82d06cf5-8286-42ea-81d3-afab4dc8cc5d'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which of the following acids is diprotic?', 'H2SO4', 'H2SO4 donates two protons, making it diprotic; others donate one proton in typical aqueous solutions.', 14),('a4c92dc1-f02f-428f-89c2-a02ff1622098'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which oxide is amphoteric?', 'Al2O3', 'Al2O3 is amphoteric, reacting with both acids and bases; the others are basic oxides.', 15),('4cef166e-1d34-4174-8cc9-39b6c3b94f0d'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Explain why ammonia is considered a weak base in aqueous solution.', 'Ammonia (NH3) is a weak base because it partially accepts a proton in water to form NH4+ and OH-, with an equilibrium that lies to the left; the base dissociation constant Kb is small, indicating limited hydroxide production.', 'NH3 + H2O ⇌ NH4+ + OH-; Kb is about 1.8×10^-5; not all NH3 molecules form OH-; thus weaker than strong bases like NaOH.', 16),('0f249d6e-b751-4149-8275-bfece4d213d9'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Calculate the pH of a 0.10 M HCl solution.', '1.0 (pH)', 'Hydrochloric acid is a strong acid; [H+] ≈ 0.10 M, pH = -log10(0.10) = 1.0.', 17),('d012a400-5f86-4230-8a19-7ad0c80e31d0'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Calculate the number of moles in 5.00 g of NaCl.', '0.0856 mol', 'Molar mass NaCl = 58.44 g/mol; moles = mass / molar mass = 5.00 / 58.44 ≈ 0.0856 mol.', 18),('76ce830a-578b-4c57-8ffc-f8f44e718cb3'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which statement about salt formation from acids and bases is correct?', 'Salts form from neutralization of an acid with a base; the cation comes from the base and the anion from the acid.', 'During neutralization, an acid and base produce a salt and water; the salt carries ions from both reactants; aqueous salt solutions conduct electricity due to mobile ions.', 19),('35b7dda8-3926-4309-85df-6885a7ef7b0b'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which oxide is formed when magnesium burns in air?', 'MgO', 'Magnesium reacts with oxygen to form magnesium oxide MgO, a basic oxide.', 20),('96ba2752-64fe-4bc7-8c02-14a87860801f'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'In water, Arrhenius acids yield which ion?', 'H+', 'Arrhenius acids increase the concentration of hydrogen ions (H+) in aqueous solution (often represented as H3O+).', 21),('51f6643b-298b-4234-87ba-9ce858e3ed57'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which reaction type produces a salt and water when an acid reacts with a base?', 'Neutralization', 'Acid-base neutralization yields a salt and water.', 22),('f7512632-8a4a-4b08-8dad-1f03167e98b7'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Metal oxides reacting with acids are classified as which type of oxide?', 'Basic oxide', 'Metal oxides that react with acids to form a salt are basic oxides.', 23),('72da9b1e-1498-4e1d-8856-107f550925b5'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'When NaOH reacts with H2SO4, which salt is formed?', 'Na2SO4', 'Neutralization of NaOH with H2SO4 yields sodium sulfate Na2SO4.', 24),('9a6b7c7b-546f-4dad-89f7-3d8288cf6518'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Name two evidences that a chemical change has occurred.', 'Formation of a precipitate and evolution of gas (gas production); color change; temperature change.', 'Chemical changes typically show precipitate formation, gas production, color changes, or temperature changes.', 25),('cc801ffb-8e83-45f4-859d-47aaa8c203ff'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Define Arrhenius acid.', 'An Arrhenius acid is a substance that increases the concentration of H+ (or H3O+) ions in aqueous solution.', 'Arrhenius acids dissociate in water to produce H+ ions; the classic definition.', 26),('af411cfd-abd0-49de-85ce-c87527878fa6'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'In the reaction H2SO4 + 2 NaOH → Na2SO4 + 2 H2O, if 0.180 mol H2SO4 reacts with 0.360 mol NaOH, how many moles of Na2SO4 are formed and what is its mass in grams?', '0.180 mol Na2SO4 formed; mass = 25.57 g Na2SO4', 'The balanced equation shows 1 mol H2SO4 produces 1 mol Na2SO4; H2SO4 is limiting (0.180 mol), so Na2SO4 formed = 0.180 mol; Mass = 0.180 x 142.04 g/mol = 25.57 g.', 27),('556de112-75cf-4036-8efc-672a408a336d'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'true_false', 'True or False: All metal oxides are basic oxides.', 'False', 'Some metal oxides can be amphoteric or behave as acids under certain conditions; not all are strictly basic.', 28),('c5d1ef4a-6bd6-42c3-81fe-3ba6da3197cc'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'Calculate the mass percent composition of sodium chloride (NaCl). Use Na = 22.99 g/mol and Cl = 35.45 g/mol.', 'Na: 39.34%; Cl: 60.66%', 'Molar mass NaCl = 22.99 + 35.45 = 58.44 g/mol. Mass% Na = 22.99/58.44 × 100 = 39.34%; Cl = 35.45/58.44 × 100 = 60.66%.', 29),('32ebd171-b852-424c-838c-bdcf96b75016'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which statement best defines a chemical reaction as used in Unit 3?', 'A process that forms new substances with different properties', 'A chemical reaction involves the transformation of reactants into products with new properties, as described in 3.1 Introduction.', 30),('a0b4b0b0-0fcd-404e-855d-bf5784e021c6'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which oxide is typically basic and reacts with water to form a hydroxide?', 'MgO', 'Metal oxides like MgO form basic hydroxides when dissolved; CO2 and SO3 form acidic oxides; SiO2 is largely acidic/neutral.', 31),('537fe63d-0a98-4dfe-858d-5f75db61c3d9'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which of the following is an Arrhenius acid?', 'HCl', 'Arrhenius acids release H+ in water; HCl is a classic example.', 32),('c2e7e789-bef0-4e3b-8ba1-a56160b1d93b'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which substance is an Arrhenius base?', 'NaOH', 'Arrhenius bases release OH- in water; NaOH is a base.', 33),('0f36f2ba-3024-4332-8902-c5a919f8f39e'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'multiple_choice', 'Which of the following is a salt?', 'NaCl', 'A salt is an ionic compound formed from neutralization; NaCl is a typical example.', 34),('61bb5902-ecdd-4d53-8e41-74e8af53759c'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'true_false', 'Sodium oxide reacts with water to form sodium hydroxide.', 'True', 'Na2O + H2O → 2 NaOH; Na2O is a basic oxide.', 35),('1097d034-778a-4b41-8298-be4e8fba768c'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'State the Arrhenius definition of an acid.', 'An Arrhenius acid is a substance that increases the concentration of H+ (H3O+) ions in aqueous solution.', 'Arrhenius acids dissociate to give H+ ions in water, a foundational definition for acids in section 3.3.', 36),('bf8d71a1-9b9a-4a7a-8f67-43a1980623da'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'State the Arrhenius definition of a base.', 'A substance that increases OH- ions in aqueous solution.', 'Arrhenius bases dissociate to give OH- ions in water, a foundational definition for bases in section 3.4.', 37),('546b2605-6c1b-445a-837c-428417b08397'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'A 25.0 mL sample of 1.00 M HCl is reacted with excess solid Na2CO3 to form NaCl. (a) How many grams of NaCl are produced? (b) Show your calculation steps and final unit.', '1.461 g', 'Moles HCl = 0.0250 L × 1.00 mol/L = 0.0250 mol. Reaction: Na2CO3 + 2 HCl → 2 NaCl + CO2 + H2O. NaCl formed = equal to HCl moles (1:1 after simplification), so 0.0250 mol NaCl. Mass NaCl = 0.0250 mol × 58.44 g/mol = 1.461 g.', 38),('1e46da16-a3ea-4dbd-88a0-b691ec8a9465'::uuid, '0b212d6e-94d4-4ec4-89be-d7e81f1cf9b9'::uuid, 'fill_blank', 'From 10.0 g of Na2CO3 reacting with 2.00 L of 0.100 M HCl, calculate the mass of NaCl produced. (Reaction: Na2CO3 + 2 HCl → 2 NaCl + CO2 + H2O)', '11.0 g', 'Moles Na2CO3 = 10.0 g / 105.99 g/mol ≈ 0.0943 mol. Moles HCl provided = 2.00 L × 0.100 M = 0.200 mol. Na2CO3 is limiting (needs 0.1886 mol HCl to react with all Na2CO3). NaCl produced = 2 × 0.0943 mol = 0.1886 mol. Mass NaCl = 0.1886 mol × 58.44 g/mol ≈ 11.02 g ≈ 11.0 g.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('26af57c0-0d14-47b5-8c05-f5b3765f8801'::uuid, 'a8fdf994-6c2a-4c19-896a-0e472d1bdad7'::uuid, 'A) ice melts', FALSE, 0),('33a78144-e0d1-405d-8b54-4389e46c1bbc'::uuid, 'a8fdf994-6c2a-4c19-896a-0e472d1bdad7'::uuid, 'B) rusting of iron', TRUE, 1),('66485ffa-b2e2-4001-84b8-63e22552c391'::uuid, 'a8fdf994-6c2a-4c19-896a-0e472d1bdad7'::uuid, 'C) sugar dissolves in tea', FALSE, 2),('2484fd67-0b80-4f17-8dec-b16a645044d5'::uuid, 'a8fdf994-6c2a-4c19-896a-0e472d1bdad7'::uuid, 'D) evaporation of water', FALSE, 3),('10ad92e1-27aa-44e2-88e8-d8ac5a5f95b3'::uuid, '0fbf2e83-aec7-436d-8865-d64b7358cf29'::uuid, 'Na2O', FALSE, 0),('335fc3cc-9dfd-49c5-8d18-65f2a8bea8d7'::uuid, '0fbf2e83-aec7-436d-8865-d64b7358cf29'::uuid, 'SO3', TRUE, 1),('f89c6d29-d91f-4891-87ed-c0b614520586'::uuid, '0fbf2e83-aec7-436d-8865-d64b7358cf29'::uuid, 'MgO', FALSE, 2),('dfe4d32c-9431-4256-882b-5f2dc869802d'::uuid, '0fbf2e83-aec7-436d-8865-d64b7358cf29'::uuid, 'K2O', FALSE, 3),('ad283cfb-0b6e-4178-8e60-14f85f18f0bb'::uuid, '12a91b2c-2e65-400f-859e-6ab2a43b6976'::uuid, 'They turn blue litmus red', TRUE, 0),('04a34172-2cc9-491a-8228-bfd6f34fd284'::uuid, '12a91b2c-2e65-400f-859e-6ab2a43b6976'::uuid, 'They turn red litmus blue', FALSE, 1),('109e8125-36e0-44cd-85f4-061b5ac256dc'::uuid, '12a91b2c-2e65-400f-859e-6ab2a43b6976'::uuid, 'They do not conduct electricity in aqueous solution', FALSE, 2),('d1cf412d-8233-48ca-8433-dba4f91b8d1e'::uuid, '12a91b2c-2e65-400f-859e-6ab2a43b6976'::uuid, 'They have pH > 7', FALSE, 3),('dc6ab1fd-9232-4ec4-87c1-c22372e018f6'::uuid, '5b679fd3-942f-4958-80ac-246355cced4f'::uuid, 'They turn blue litmus red', FALSE, 0),('7074efec-8521-4e98-87b7-42845675ea41'::uuid, '5b679fd3-942f-4958-80ac-246355cced4f'::uuid, 'They turn red litmus blue', TRUE, 1),('b6ef75c7-f233-4930-8a0b-42fe73fe1eac'::uuid, '5b679fd3-942f-4958-80ac-246355cced4f'::uuid, 'They have sour taste', FALSE, 2),('0a9eb2f4-c68e-4b26-8e17-920492d9b42b'::uuid, '5b679fd3-942f-4958-80ac-246355cced4f'::uuid, 'They do not react with acids', FALSE, 3),('a9be84a6-43ba-4e4d-83f1-7d5696c95f65'::uuid, '7b8785e6-9b35-4582-8e29-009292d258c6'::uuid, 'All salts yield acidic solutions in water', FALSE, 0),('7def6140-df03-439d-800e-761c6e7b55a0'::uuid, '7b8785e6-9b35-4582-8e29-009292d258c6'::uuid, 'Salts are formed by the neutralization of acids and bases', TRUE, 1),('9835f14a-0332-4550-803f-822b8c1569d3'::uuid, '7b8785e6-9b35-4582-8e29-009292d258c6'::uuid, 'All salts are soluble in water', FALSE, 2),('23a2a802-689c-422e-8f99-892c6776cc79'::uuid, '7b8785e6-9b35-4582-8e29-009292d258c6'::uuid, 'Salts contain the hydronium ion in solution', FALSE, 3),('c419c219-0565-445d-86ea-61576f0f0243'::uuid, '50c7e2ee-54d2-4f0e-8c65-774ce32e1087'::uuid, 'True', FALSE, 0),('053bb0ef-dda0-49ae-83d4-ff3bd6a4f145'::uuid, '50c7e2ee-54d2-4f0e-8c65-774ce32e1087'::uuid, 'False', TRUE, 1),('6b9dda87-bb37-42a1-8b46-1fcbd1b9e8a5'::uuid, 'b07ef478-01c0-496d-8bc8-8ecd460caf29'::uuid, 'An oxide is a compound containing only oxygen.', FALSE, 0),('09f1a206-334c-4fb0-8a5f-03ddddf36b77'::uuid, 'b07ef478-01c0-496d-8bc8-8ecd460caf29'::uuid, 'An oxide is a compound formed when oxygen combines with another element.', TRUE, 1),('2b9a07de-5ac4-4ee7-8a7e-86de0e926ecb'::uuid, 'b07ef478-01c0-496d-8bc8-8ecd460caf29'::uuid, 'All oxides are acidic in water.', FALSE, 2),('45912e40-1441-423c-8f78-c55a56946282'::uuid, 'b07ef478-01c0-496d-8bc8-8ecd460caf29'::uuid, 'Metal oxides do not react with water.', FALSE, 3),('16ea03e1-0521-44c9-8572-3e59bc95f3e0'::uuid, '109caf21-3e64-4d1b-8e51-80f12c6f2f76'::uuid, 'H2SO4', FALSE, 0),('1f1a680a-1b13-4a57-8c9f-0e64de93b8f0'::uuid, '109caf21-3e64-4d1b-8e51-80f12c6f2f76'::uuid, 'NaOH', TRUE, 1),('8cf4fa2c-4991-4f89-8cc5-60f5dd7d018b'::uuid, '109caf21-3e64-4d1b-8e51-80f12c6f2f76'::uuid, 'CO2', FALSE, 2),('0865aa52-93b6-49f9-8c6e-6f42b7b68547'::uuid, '109caf21-3e64-4d1b-8e51-80f12c6f2f76'::uuid, 'NH4Cl', FALSE, 3),('58167920-00b7-415