INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'Chemistry', 'Unit 6', 'Molarum Grade 10 — Chemistry HYDROCARBONS AND THEIR NATURAL SOURCES', 'Source-grounded Molarum Grade 10 Chemistry questions for HYDROCARBONS AND THEIR NATURAL SOURCES.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('bce62f03-578d-4c86-8b42-928e481c46f5'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which general formula represents saturated hydrocarbons (alkanes)?', 'CnH2n+2', 'Alkanes have formula CnH2n+2; each carbon adds two hydrogens.', 0),('5f92a65d-ab19-46cc-850f-87591448c81d'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which alkane has five carbon atoms?', 'Pentane', 'General formula CnH2n+2 with n=5 yields C5H12.', 1),('ad644655-a48e-4212-8aeb-35352f2e7438'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which class of hydrocarbons does cyclohexane belong to?', 'Cycloalkane', 'Cycloalkanes are alicyclic hydrocarbons with ring structures that are not aromatic.', 2),('afd6e951-296e-473c-8cbe-dc7e741ce4b9'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which statement best describes benzene?', 'It is aromatic with delocalized electrons', 'Benzene is an aromatic hydrocarbon with a stable ring system of delocalized electrons.', 3),('c33c80e3-70ae-4c84-8fb9-f52d9bfec7af'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'What is the correct IUPAC name for benzene with a chlorine substituent at position 1 and a methyl substituent at position 2?', '1-chloro-2-methylbenzene', 'For adjacent substituents on a benzene ring, the locants are 1 and 2; substituents are listed in alphabetical order (chloro before methyl) leading to 1-chloro-2-methylbenzene.', 4),('80399c9c-e455-4f40-8d0a-c56c17503670'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Natural gas is primarily composed of methane.', 'True', 'Natural gas is dominated by methane, with smaller amounts of other hydrocarbons.', 5),('0f356b77-0607-461a-880a-9de87ec13c7a'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'State the general formula for alkanes and write the corresponding formula for an alkane with n = 6.', 'General formula: CnH2n+2; for n=6: C6H14', 'Alkanes follow CnH2n+2; substituting n=6 gives C6H14.', 6),('8932f09c-df4c-4339-83e1-fc8db51dc758'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Name two cycloalkanes commonly discussed in Unit 6.', 'Cyclopentane and cyclohexane', 'Examples of cycloalkanes (Alicyclic hydrocarbons) often cited are cyclopentane and cyclohexane.', 7),('17054ff8-3b50-4986-85bd-7aa6b9922621'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Using the alkane general formula CnH2n+2, determine the number of hydrogen atoms in the alkane with n = 7.', 'C7H16', 'Hydrogen count is H = 2n + 2; for n = 7, H = 16; thus C7H16.', 8),('2f949331-5cd2-4bc1-8f74-8ad625de6767'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'From the general formula for alkanes, determine the number of hydrogen atoms in decane (C10H22).', '22', 'For n = 10, H = 2n + 2 = 22. Final molecular formula is C10H22 (hydrogen atoms = 22).', 9),('9612ba31-99eb-4132-8719-cf7ceca63a1e'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'What is the IUPAC name of the alkane with five carbon atoms in a straight chain?', 'Pentane', 'Five carbon atoms in a straight chain correspond to pentane (C5H12).', 10),('73d89eac-31ab-4254-8b26-dd4219f9681b'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which statement about alkanes is true?', 'They are saturated hydrocarbons', 'Alkanes are saturated hydrocarbons because they contain only single bonds between carbon atoms.', 11),('28d2a2d6-eccd-44f9-888e-550da15c6e58'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which natural source primarily contains methane, ethane, propane, and butane?', 'Natural gas', 'Natural gas is a major source of light hydrocarbons including methane, ethane, propane and butane.', 12),('3645f57b-a527-4e1c-8116-0caf80c86061'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which molecule contains a carbon-carbon double bond?', 'Ethene', 'Ethene (C2H4) contains a C=C double bond; others listed have only single bonds.', 13),('4595ec4a-8d10-42c9-83e1-73ddf8f1cc17'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'In benzene, which statement about C-C bonds is correct?', 'All C-C bonds are identical and intermediate between single and double', 'Benzene has delocalized electrons; the C-C bonds are equivalent and of intermediate character due to resonance.', 14),('632df67f-8a09-4354-86f0-608042dd6030'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'true_false', 'Alkanes burn in air to form carbon dioxide and water.', 'True', 'Complete combustion of alkanes yields CO2 and H2O.', 15),('1681068c-cd05-44b9-8dbc-f90829351911'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Name one common use of alkanes.', 'Fuel for heating and transportation', 'Alkanes are widely used as fuels for heating and transportation.', 16),('9273cca8-5349-40bf-8e99-c6fc2eb5bbad'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Give one reason why alkanes are relatively unreactive.', 'They contain only C–C and C–H single bonds and lack pi (double) bonds.', 'Alkanes have only sigma bonds (C–C, C–H) and no C=C or pi bonds, making many reactions less favorable.', 17),('f121977c-1166-4d3d-8fdd-2c2985195693'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Calculate the mass of CO2 produced when 16.0 g of methane (CH4) is burned completely in oxygen. Use the reaction CH4 + 2 O2 → CO2 + 2 H2O; molar masses: CH4 = 16.04 g/mol, CO2 = 44.01 g/mol.', '43.9 g', '1) Moles CH4 = 16.0 g / 16.04 g/mol ≈ 0.9975 mol. 2) Stoichiometry: 1 mol CH4 → 1 mol CO2, so moles CO2 ≈ 0.9975 mol. 3) Mass CO2 = 0.9975 mol × 44.01 g/mol ≈ 43.9 g. Final unit: grams of CO2.', 18),('f971ef2f-e103-4f7e-8ae1-9ace8633053b'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'At STP, 2.00 L of ethene gas (C2H4) reacts with hydrogen to form ethane (C2H6) in a 1:1 mole ratio. If this gas mixture is pure ethene and hydrogen is in excess, how many grams of ethane are formed? Provide the final answer with appropriate units and show the method.', '2.69 g', '1) At STP, n(C2H4) = PV/RT = (1 atm × 2.00 L) / (0.082057 L·atm/mol·K × 273.15 K) ≈ 0.0893 mol. 2) Stoichiometry: 1 mol C2H4 → 1 mol C2H6, so n(C2H6) ≈ 0.0893 mol. 3) Mass of C2H6 = 0.0893 mol × 30.07 g/mol ≈ 2.69 g.', 19),('f6d3854a-a38d-4b00-8f81-33345a06c1c5'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'What is the IUPAC name for the alkane with the formula C4H10 in its straight-chain form?', 'Butane', 'C4H10 corresponds to alkanes with n=4; the straight-chain alkane with four carbons is butane. The general formula for alkanes is CnH2n+2.', 20),('8639211f-ee91-4d77-8516-e7a1a53a6e25'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which statement best describes the physical properties of alkanes (saturated hydrocarbons)?', 'They are nonpolar and have relatively low boiling points compared with many other organic compounds of similar size.', 'Alkanes are nonpolar with London dispersion forces; boiling points rise with chain length but are generally low compared with compounds with hydrogen bonding or polarity.', 21),('74fd7bcb-5a8f-4cbd-8e9f-2657055722aa'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'true_false', 'Natural gas is primarily composed of methane (Distinct application example 23.)', 'True', 'The major component of natural gas is methane (CH4).', 22),('2e9f8e96-8ea7-47e6-89be-915a453ab089'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'What is the general formula for acyclic alkenes (the simplest class of unsaturated hydrocarbons)?', 'CnH2n', 'Alkenes have two fewer hydrogens than the corresponding alkane (CnH2n).', 23),('b3c8d404-4f16-4711-8eb6-b26bf1554bbd'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which statement about benzene is true?', 'It has equal bond lengths due to delocalized electrons around the ring.', 'Benzene’s π-electrons are delocalized, giving equal bond lengths and aromatic stability.', 24),('7145cb6d-0fe5-4127-8c71-0adaa84aaae7'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'true_false', 'Natural gas is primarily methane.', 'True', 'The major component of natural gas is methane (CH4).', 25),('d861b905-5503-4bfa-8850-3f8bdc1ae494'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Name one natural source of hydrocarbons mentioned in Unit 6.', 'Natural gas', 'Unit 6 discusses natural sources including natural gas, petroleum, and coal.', 26),('2f1db948-a396-414e-89d9-8b5935af5450'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Explain briefly why alkanes are relatively unreactive.', 'Alkanes are relatively unreactive because they have nonpolar C–H and C–C bonds with no functional groups; they lack polarity and thus do not participate in many typical chemical reactions except under harsh conditions (e.g., combustion or radical substitution with halogens under UV light).', 'Without polar functional groups and with weak London forces, C–H and C–C bonds require significant energy to break; typical reactions are limited to combustion or, under UV light, substitution with halogens.', 27),('02b87d9c-0b9a-46ea-8d55-99b67b883742'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Calculate the molar mass of octane, C8H18.', '114.22 g/mol', 'M = (8 × 12.01 g/mol) + (18 × 1.008 g/mol) = 96.08 g/mol + 18.144 g/mol = 114.224 g/mol ≈ 114.22 g/mol.', 28),('4ffebaa2-81d4-42ca-8fb8-3a4ddf046c67'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'How many grams of ethane (C2H6, molar mass 30.07 g/mol) are required to obtain 2.00 moles?', '60.14 g', 'Mass = moles × molar mass; m = 2.00 mol × 30.07 g/mol = 60.14 g. Final unit: grams (g).', 29),('3f85d3fc-6116-4d04-81fd-c3145c6dd64e'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which statement best describes the trend in boiling points of straight-chain alkanes as the carbon chain length increases?', 'C. Boiling points increase as chain length increases.', 'Longer carbon chains have stronger van der Waals forces, leading to higher boiling points as chain length increases.', 30),('9ba5bc3a-cf46-409a-8d5c-7e71864aaef6'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'What is the IUPAC name for the straight-chain alkane with 5 carbons?', 'A. Pentane', 'Five-carbon straight chain corresponds to pentane in IUPAC nomenclature.', 31),('3d77ef45-4877-4da6-808c-b930fcb83985'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'An alkane with 6 carbon atoms has the formula C6H14. Determine its approximate molar mass in g/mol.', '86.17', 'Molar mass = (6 × 12.01) + (14 × 1.008) = 72.06 + 14.112 ≈ 86.17 g/mol.', 32),('0998db98-3535-4f2e-8f91-953e8f278f43'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'Which statement about cycloalkanes is true?', 'B. They have the general formula CnH2n.', 'Cycloalkanes are saturated ring compounds with the formula CnH2n, unlike open-chain alkanes (CnH2n+2).', 33),('16b4d972-d559-493f-811c-a8df95bef6d2'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'What is the general formula for saturated acyclic alkanes?', 'B. CnH2n+2', 'Acyclic saturated alkanes follow the formula CnH2n+2.', 34),('90192028-7f37-4f67-8711-07419ea97071'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'multiple_choice', 'In the free-radical chlorination of alkanes under UV light, which step is the chain-propagating step that forms the alkyl radical?', 'B. Propagation', 'Propagation steps involve the formation and consumption of radicals that propagate the chain reaction.', 35),('0ff12fb8-c1ae-4676-831d-843a0193f529'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'true_false', 'Cycloalkanes have the general formula CnH2n+2.', 'False', 'Cycloalkanes have the formula CnH2n, not CnH2n+2; alkenes have CnH2n.', 36),('21d13f53-8943-4cae-816e-884383f25f5e'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'Name two natural sources of hydrocarbons.', 'Natural gas and crude oil (petroleum)', 'Two major natural hydrocarbon sources listed in Unit 6: natural gas and crude oil.', 37),('aadc60a4-10e7-457e-8129-4f333830ad2a'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'State the general formulas for open-chain alkanes and cycloalkanes.', 'Open-chain alkanes: CnH2n+2; Cycloalkanes: CnH2n', 'Open-chain alkanes follow CnH2n+2 while cycloalkanes follow CnH2n.', 38),('9d2d2bc4-f9e9-4ac3-8fb4-6dba163fae54'::uuid, 'de4a1423-93ba-4101-87af-c5f32a78e055'::uuid, 'fill_blank', 'A natural gas sample contains 60% methane (CH4), 25% ethane (C2H6), and 15% propane (C3H8) by mole. Calculate the mean molar mass of the gas in g/mol.', '23.76', 'Mean molar mass M = 0.60(16.04) + 0.25(30.07) + 0.15(44.10) = 9.624 + 7.5175 + 6.615 ≈ 23.76 g/mol.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('229684cd-7cec-4acc-8499-3921f66e34e0'::uuid, 'bce62f03-578d-4c86-8b42-928e481c46f5'::uuid, 'CnH2n', FALSE, 0),('0eed7b79-441c-461f-8325-b26090f127f2'::uuid, 'bce62f03-578d-4c86-8b42-928e481c46f5'::uuid, 'CnH2n+2', TRUE, 1),('379cbdae-a902-40cd-8855-351b71b882ab'::uuid, 'bce62f03-578d-4c86-8b42-928e481c46f5'::uuid, 'CnH2n+1', FALSE, 2),('755ed83a-340d-4463-82d9-5b670e796b8f'::uuid, 'bce62f03-578d-4c86-8b42-928e481c46f5'::uuid, 'CnH2n+4', FALSE, 3),('09c0a4ae-82a6-45f4-8b2c-9add20a1a1b7'::uuid, '5f92a65d-ab19-46cc-850f-87591448c81d'::uuid, 'Methane', FALSE, 0),('d1c3a4bb-9bd8-4ea0-8468-1dbc18ddb09f'::uuid, '5f92a65d-ab19-46cc-850f-87591448c81d'::uuid, 'Pentane', TRUE, 1),('ab18c293-1023-4b91-8796-3a68fc579a65'::uuid, '5f92a65d-ab19-46cc-850f-87591448c81d'::uuid, 'Hexane', FALSE, 2),('5fbfe853-55bd-4aa0-8567-406222a5fe2a'::uuid, '5f92a65d-ab19-46cc-850f-87591448c81d'::uuid, 'Butane', FALSE, 3),('dd97f2b7-bcd1-4651-8d4e-721cd6955dad'::uuid, 'ad644655-a48e-4212-8aeb-35352f2e7438'::uuid, 'Alkene', FALSE, 0),('a2535de9-d559-49a8-8ca5-0bb267eed61f'::uuid, 'ad644655-a48e-4212-8aeb-35352f2e7438'::uuid, 'Alkyne', FALSE, 1),('5d21d155-25e7-4579-8258-0fee05b67561'::uuid, 'ad644655-a48e-4212-8aeb-35352f2e7438'::uuid, 'Cycloalkane', TRUE, 2),('803a18c1-530f-4058-8895-ffd192358710'::uuid, 'ad644655-a48e-4212-8aeb-35352f2e7438'::uuid, 'Aromatic', FALSE, 3),('0cc4f509-49c3-4f44-8ac1-d8704dc19d6d'::uuid, 'afd6e951-296e-473c-8cbe-dc7e741ce4b9'::uuid, 'It is a saturated hydrocarbon', FALSE, 0),('aa07b0a1-1fb3-4843-814e-b43b9f950a21'::uuid, 'afd6e951-296e-473c-8cbe-dc7e741ce4b9'::uuid, 'It is aromatic with delocalized electrons', TRUE, 1),('6f563469-80e2-45de-8764-b2a0f0ff29d4'::uuid, 'afd6e951-296e-473c-8cbe-dc7e741ce4b9'::uuid, 'It contains a single carbon ring with alternating single bonds only', FALSE, 2),('349ba48d-f4b5-4fe9-81c8-18ad955ba3f2'::uuid, 'afd6e951-296e-473c-8cbe-dc7e741ce4b9'::uuid, 'It has no ring structure', FALSE, 3),('f0ac0502-b67b-47d6-8701-8ab21b6a8e43'::uuid, 'c33c80e3-70ae-4c84-8fb9-f52d9bfec7af'::uuid, '1-chloro-2-methylbenzene', TRUE, 0),('57db38b2-ca0d-4385-893a-07173f38cde6'::uuid, 'c33c80e3-70ae-4c84-8fb9-f52d9bfec7af'::uuid, '2-chloro-1-methylbenzene', FALSE, 1),('20ea51e8-cbfa-4e45-890f-e17b27121949'::uuid, 'c33c80e3-70ae-4c84-8fb9-f52d9bfec7af'::uuid, '1-methyl-2-chlorobenzene', FALSE, 2),('65f33888-cdb0-4516-85a5-121c6b5e4153'::uuid, 'c33c80e3-70ae-4c84-8fb9-f52d9bfec7af'::uuid, '3-chloro-1-methylbenzene', FALSE, 3),('d4a7baae-e06b-4f9d-81f3-89250a36071b'::uuid, '80399c9c-e455-4f40-8d0a-c56c17503670'::uuid, 'True', TRUE, 0),('3c1fa710-95d9-4bc1-870d-5bb91e445dd7'::uuid, '80399c9c-e455-4f40-8d0a-c56c17503670'::uuid, 'False', FALSE, 1),('6decc67f-590d-4184-8696-e9971a484101'::uuid, '80399c9c-e455-4f40-8d0a-c56c17503670'::uuid, 'Option 3', FALSE, 2),('9a37a4f4-3997-4e1b-8ce8-388ceeebb1a9'::uuid, '80399c9c-e455-4f40-8d0a-c56c17503670'::uuid, 'Option 4', FALSE, 3),('b7527bf7-4773-4ba9-892c-55c58a8e640d'::uuid, '9612ba31-99eb-4132-8719-cf7ceca63a1e'::uuid, 'Pentane', TRUE, 0),('8cfea4c0-dacd-4d39-8f5c-d9122b535040'::uuid, '9612ba31-99eb-4132-8719-cf7ceca63a1e'::uuid, 'Hexane', FALSE, 1),('647babce-9ebb-475d-8df7-796ea1052494'::uuid, '9612ba31-99eb-4132-8719-cf7ceca63a1e'::uuid, 'Butane', FALSE, 2),('e603774a-b4d4-4867-876e-42b125c2d7b3'::uuid, '9612ba31-99eb-4132-8719-cf7ceca63a1e'::uuid, 'Propane', FALSE, 3),('761e92a3-0efb-4cab-8462-1d78cb4c8634'::uuid, '73d89eac-31ab-4254-8b26-dd4219f9681b'::uuid, 'They are unsaturated hydrocarbons', FALSE, 0),('0321609f-5008-4f57-8fd3-7e410fef9cdf'::uuid, '73d89eac-31ab-4254-8b26-dd4219f9681b'::uuid, 'They are saturated hydrocarbons', TRUE, 1),('277567da-f2ea-4114-81f9-c4813e60b069'::uuid, '73d89eac-31ab-4254-8b26-dd4219f9681b'::uuid, 'They contain double bonds', FALSE, 2),('80e1c4b8-8b6f-4055-8330-fb33d28e9bcc'::uuid, '73d89eac-31ab-4254-8b26-dd4219f9681b'::uuid, 'They are aromatic hydrocarbons', FALSE, 3),('ec4628e5-3c6c-412e-86b4-95b50ea06a03'::uuid, '28d2a2d6-eccd-44f9-888e-550da15c6e58'::uuid, 'Natural gas', TRUE, 0),('5790eca3-be2e-483c-88c2-f230d3af79bf'::uuid, '28d2a2d6-eccd-44f9-888e-550da15c6e58'::uuid, 'Coal', FALSE, 1),('be65f5d3-ce14-4634-8709-e13ea6478005'::uuid, '28d2a2d6-eccd-44f9-888e-550da15c6e58'::uuid, 'Petroleum', FALSE, 2),('6d57b2f3-b865-4aea-8d83-9f2700bd67a2'::uuid, '28d2a2d6-eccd-44f9-888e-550da15c6e58'::uuid, 'Biomass', FALSE, 3),('2cc64305-9f06-403c-820b-41ee66a4025f'::uuid, '3645f57b-a527-4e1c-8116-0caf80c86061'::uuid, 'Ethane', FALSE, 0),('210ff8cd-6f63-448c-84b4-9185c35af66f'::uuid, '3645f57b-a527-4e1c-8116-0caf80c86061'::uuid, 'Ethene', TRUE, 1),('d4a8177e-c016-4e64-8229-999757594287'::uuid, '3645f57b-a527-4e1c-8116-0caf80c86061'::uuid, 'Butane', FALSE, 2),('8a000ade-237d-4e2b-82d5-1fe1c4869992'::uuid, '3645f57b-a527-4e1c-8116-0caf80c86061'::uuid, 'Cyclohexane', FALSE, 3),('14684f1d-8e52-4239-81dc-52ea119e3885'::uuid, '4595ec4a-8d10-42c9-83e1-73ddf8f1cc17'::uuid, 'All C-C bonds are single', FALSE, 0),('928e8338-a9e4-419a-8443-9cfd4cf2c788'::uuid, '4595ec4a-8d10-42c9-83e1-73ddf8f1cc17'::uuid, 'All C-C bonds are double', FALSE, 1),('8a706872-f569-4b6c-8990-c0036fda4f10'::uuid, '4595ec4a-8d10-42c9-83e1-73ddf8f1cc17'::uuid, 'All C-C bonds are identical and intermediate between single and double', TRUE, 2),('64f3181e-7468-48b5-86c5-9f142f64d940'::uuid, '4595ec4a-8d10-42c9-83e1-73ddf8f1cc17'::uuid, 'There are alternating single and double bonds', FALSE, 3),('8f5b35cf-f7aa-4cd4-86b0-1a5379bc20fa'::uuid, '632df67f-8a09-4354-86f0-608042dd6030'::uuid, 'True', TRUE, 0),('42c6b6f1-80b2-48d3-8fc6-3c9058a31144'::uuid, '632df67f-8a09-4354-86f0-608042dd6030'::uuid, 'False', FALSE, 1),('73f191b2-b079-42d2-8b48-bf9d81727b27'::uuid, 'f6d3854a-a38d-4b00-8f81-33345a06c1c5'::uuid, 'Methane', FALSE, 0),('58d1419e-efeb-4a18-87d4-306fc2f2edfe'::uuid, 'f6d3854a-a38d-4b00-8f81-33345a06c1c5'::uuid, 'Ethane', FALSE, 1),('1e79940d-bbc7-4bb4-857c-ccb8a