eb6-b26bf1554bbd'::uuid, 'It reacts by rapid, straightforward addition under standard conditions.', FALSE, 2),('422fe275-0aa8-4c50-8d01-ee10f81b2eaf'::uuid, 'b3c8d404-4f16-4711-8eb6-b26bf1554bbd'::uuid, 'It is not considered an aromatic compound.', FALSE, 3),('44f3a465-f997-4888-87a0-ff1ac75cee3c'::uuid, '7145cb6d-0fe5-4127-8c71-0adaa84aaae7'::uuid, 'True', TRUE, 0),('900b38a7-b596-4902-8de4-a5b6f2c15a7c'::uuid, '7145cb6d-0fe5-4127-8c71-0adaa84aaae7'::uuid, 'False', FALSE, 1),('d59716f0-51a0-4300-83b8-065dd0210697'::uuid, '3f85d3fc-6116-4d04-81fd-c3145c6dd64e'::uuid, 'A. Boiling points decrease as chain length increases.', FALSE, 0),('f06ff634-54f7-4d43-86b1-f0d0524ae5d6'::uuid, '3f85d3fc-6116-4d04-81fd-c3145c6dd64e'::uuid, 'B. Boiling points stay roughly constant.', FALSE, 1),('daf3ffd8-a619-4098-8387-b164aae29824'::uuid, '3f85d3fc-6116-4d04-81fd-c3145c6dd64e'::uuid, 'C. Boiling points increase as chain length increases.', TRUE, 2),('be314a4f-a08f-4424-88a2-fb315383be28'::uuid, '3f85d3fc-6116-4d04-81fd-c3145c6dd64e'::uuid, 'D. No general trend.', FALSE, 3),('927df3cf-f229-4f82-8e2a-df2f8137ac5f'::uuid, '9ba5bc3a-cf46-409a-8d5c-7e71864aaef6'::uuid, 'A. Pentane', TRUE, 0),('58226612-29f2-4612-85d9-572ac28f9054'::uuid, '9ba5bc3a-cf46-409a-8d5c-7e71864aaef6'::uuid, 'B. Isopentane', FALSE, 1),('1d5f1cc0-c584-4239-87b2-28d2e78fc9b5'::uuid, '9ba5bc3a-cf46-409a-8d5c-7e71864aaef6'::uuid, 'C. Cyclopentane', FALSE, 2),('9efa4197-4fa3-4072-8da7-0d05baab47a9'::uuid, '9ba5bc3a-cf46-409a-8d5c-7e71864aaef6'::uuid, 'D. Hexane', FALSE, 3),('1985d0c4-f0d0-4097-8b4a-d9a25ae7108c'::uuid, '0998db98-3535-4f2e-8f91-953e8f278f43'::uuid, 'A. They are unsaturated.', FALSE, 0),('abe94d2a-7801-41c0-8f69-eed9f5a63b32'::uuid, '0998db98-3535-4f2e-8f91-953e8f278f43'::uuid, 'B. They have the general formula CnH2n.', TRUE, 1),('c1de0f42-2cbd-4e73-888d-28561de6dab5'::uuid, '0998db98-3535-4f2e-8f91-953e8f278f43'::uuid, 'C. They always have higher boiling points than open-chain alkanes with the same carbon count.', FALSE, 2),('006a1533-02de-4670-8720-eec36d51239d'::uuid, '0998db98-3535-4f2e-8f91-953e8f278f43'::uuid, 'D. They have more hydrogens than open-chain alkanes.', FALSE, 3),('f34f6ee8-81c6-42c3-8596-9bb1b71a4231'::uuid, '16b4d972-d559-493f-811c-a8df95bef6d2'::uuid, 'A. CnH2n', FALSE, 0),('1f3391d0-9ce0-4e6e-81b4-03b596f7e2bd'::uuid, '16b4d972-d559-493f-811c-a8df95bef6d2'::uuid, 'B. CnH2n+2', TRUE, 1),('8d8dd74c-424c-4ade-888a-ab6a55fb68e8'::uuid, '16b4d972-d559-493f-811c-a8df95bef6d2'::uuid, 'C. CnH2n+4', FALSE, 2),('8b443058-8202-4452-8698-8870c72ed567'::uuid, '16b4d972-d559-493f-811c-a8df95bef6d2'::uuid, 'D. CnHn', FALSE, 3),('f07bcd26-9eb0-455e-8445-d1c91d911bcd'::uuid, '90192028-7f37-4f67-8711-07419ea97071'::uuid, 'A. Initiation', FALSE, 0),('7eb5d81b-109c-4d30-8237-3e15dced1290'::uuid, '90192028-7f37-4f67-8711-07419ea97071'::uuid, 'B. Propagation', TRUE, 1),('015104be-0a16-4d14-83f7-813f957a396f'::uuid, '90192028-7f37-4f67-8711-07419ea97071'::uuid, 'C. Termination', FALSE, 2),('6a3bd211-1b7b-44ac-8588-3bec24572664'::uuid, '90192028-7f37-4f67-8711-07419ea97071'::uuid, 'D. All of the above', FALSE, 3),('4f0c5d1b-5798-4f33-856a-138a2c24e69e'::uuid, '0ff12fb8-c1ae-4676-831d-843a0193f529'::uuid, 'True', FALSE, 0),('6cd7ebf7-780b-4774-84e0-78c4ed50d15e'::uuid, '0ff12fb8-c1ae-4676-831d-843a0193f529'::uuid, 'False', TRUE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'Citizenship', 'Unit 1', 'Molarum Grade 10 — Citizenship Unit 1: Democracy and Democratization', 'Source-grounded Molarum Grade 10 Citizenship questions for Unit 1: Democracy and Democratization.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'According to the textbook, from which two Greek words is the term ''democracy'' derived?', 'From the Greek words ''Demo'' and ''Kratos'' meaning people and rule', 'The excerpt states the word democracy was derived from the Greek words ''Demo'' and ''Kratos'', meaning people and rule respectively.', 0),('7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which dictionary-style definition of democracy is given in the excerpt?', 'A state of government in which people hold ruling power directly or indirectly through elected representatives', 'The textbook defines democracy as a state of government in which people hold ruling power either directly or indirectly through elected representatives.', 1),('a105324a-e809-4965-8842-2cfa1ae58861'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which set of values does the textbook list as central to democracy?', 'Liberty (freedom), Justice, and Equality', 'The excerpt states three core values central to democracy are liberty/freedom, justice and equality.', 2),('df768498-2b6e-4443-8a3f-7c6bca25d0ce'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following best describes ''democratization'' as given in the book?', 'A complex, long-term, dynamic and open-ended process toward a more democratic political regime', 'The textbook describes democratization as a complex, long-term, dynamic and open-ended process that moves a political system toward democracy.', 3),('875b5f28-1b05-462a-825d-014e85872228'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is explicitly named as an actor in the democratization process in the excerpt?', 'Political parties', 'The excerpt names political parties as vectors of democracy and actors in the democratization process.', 4),('b8953843-d1c5-4004-89f4-80d0df4c851b'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is NOT presented in the text as an actor in the democratization process?', 'Weather systems', 'The excerpt lists political parties, civil societies and interest groups as actors, but does not present weather systems as actors in democratization.', 5),('58ceedaa-2016-4d40-83ed-56055aff5012'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'According to the book, what primary role do political parties play in democracy?', 'They are instruments through which power is attained by means of free, fair and transparent elections', 'The textbook states political parties are instruments through which power is attained by means of free, fair and transparent elections and are vectors of democracy.', 6),('de1ff582-302b-4517-8716-063fbdb1e66d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'How does the textbook distinguish civil societies from political parties?', 'They differ in final goal but both contribute to consciousness raising and protection of rights', 'The excerpt explains that civil societies differ from political parties in their final goal but both contribute to consciousness-raising and defense of rights and freedoms.', 7),('30edd166-638f-4abb-8818-8ce9cc9ac76d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which role of interest groups is described in the excerpt?', 'They act as transmission belts between people and government', 'The textbook states interest groups are regarded as essential transmission belts between people and government, helping citizens communicate policy wants to leaders.', 8),('33a61744-31b7-4fcc-8759-38d0bc7372b7'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'What condition does the excerpt say the media must satisfy to perform its democratic functions?', 'Be free and independent with sufficient material and human resources', 'The excerpt explains media must be free and independent and have sufficient material and human resources to perform political training and build democratic culture.', 9),('a32bdb28-69b8-43a8-87d8-8fb7d950375f'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is listed as a function of the Independent National Electoral Commission in the text?', 'Registers voters', 'The INEC functions listed in the excerpt include registering voters among other electoral responsibilities.', 10),('bfe36918-f29c-4824-8c1c-546854c4c1f4'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is one of the INEC''s specific duties as given in the textbook?', 'Provides security at the polling stations', 'The textbook lists ''provides security at the polling stations'' among the INEC''s functions.', 11),('c19aee6e-bff6-4424-8285-415b33f059ac'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which is one of the functions of political parties according to the excerpt?', 'Serve as a forum for national unity and mutual understanding', 'The excerpt lists serving as a forum for national unity and mutual understanding as a function of political parties.', 12),('6ab0080c-81ef-42da-8878-a68539f8471c'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is listed as a function of a pressure group in the book?', 'Acts as a watchdog over public policies', 'The excerpt states pressure groups act as watchdogs over public policies among other functions.', 13),('3e436b1b-ba5d-46ef-8d0d-803bee50fd26'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is NOT described in the excerpt as a component of ''liberty'' in democracy?', 'Procedural justice', 'The textbook lists personal, political and economic freedoms under liberty; procedural justice is described under the value of justice, not liberty.', 14),('334c0d7c-cadb-4c41-86b5-c997ee00b2eb'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of these is given as a general sense of ''justice'' in the excerpt?', 'Distributive justice', 'The excerpt describes distributive justice (among others) as a general sense of the value of justice.', 15),('bd39d45e-4ca7-4834-8c90-0538a65d7a36'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'What does ''political equality'' imply in the book''s discussion of equality?', 'All adults have equal political rights (one person, one vote)', 'The excerpt states political equality implies all people who attain adulthood have equal political rights, summarized as one man-one vote-one value.', 16),('f04fa500-1c71-4eb5-8bd5-f03d41700053'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which describes the economic aspect of democracy as given in the text?', 'Equitable and just distribution of wealth and resources and recognition of rights to work and fair wages', 'The excerpt explains the economic aspect means equitable distribution of wealth, right to work, fair wages, and enjoyment of life.', 17),('c3a53e01-73eb-48eb-8c41-bc4eb7a2456d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which phrase from the excerpt is used to describe democratization?', 'Complex, long-term, dynamic and open-ended process', 'The textbook explicitly describes democratization using the phrase ''complex, long-term, dynamic, and open-ended process''.', 18),('857cdc90-df04-4676-88d7-e2224f0efd9d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'How many lessons are listed under Unit 1 in the textbook?', 'Six', 'The excerpt lists six lessons for the unit: the concept of democracy and democratization; actors; institutionalizing democracy; role for social transformation; democratic values; and aspects of democracy.', 19),('9a0141a0-dd9e-4b96-830c-f41f1a60bc4f'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'The word democracy was derived from two Greek words: demos and kratos, which means common people and rule respectively.', 'True', 'The textbook explicitly states democracy was derived from demos and kratos meaning people and rule.', 20),('deadc2e6-9b04-4ef5-837a-fa67e0dbcbc3'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'A democratic system is the one in which citizens freely make political decisions by majority rule.', 'True', 'The unit review includes the statement that a democratic system is where citizens freely make political decisions by majority rule.', 21),('7394367f-94b7-4f81-8031-f6fc5d475fe1'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'Political parties are organized groups of individuals who share different political ideologies, beliefs and interests.', 'False', 'The excerpt defines political parties as organized groups who share the same political ideologies, beliefs and interests, so the statement claiming ''different'' is incorrect.', 22),('ede66253-225c-4e2a-8b4b-ea19833ae585'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'Like political parties, interest groups are valuable vectors of democracy.', 'True', 'The excerpt states that, like political parties, non-governmental associations and organizations (interest groups) are valuable vectors of democracy.', 23),('7f479b17-d59d-4a9d-82d3-3db5c27dc57f'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'In your own words based only on the excerpt, define ''democracy''.', 'A state of government in which people hold the ruling power either directly or indirectly through their elected representatives, implying rule by the people.', 'The excerpt defines democracy as rule by the people, where people hold ruling power directly or through elected representatives.', 24),('639f2109-3609-4c12-8c4c-95fa6d91ec11'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Explain the meaning of ''democratization'' according to the textbook.', 'Democratization is a complex, long-term, dynamic and open-ended political process of transition toward a more rule-based, consensual and participatory democratic political regime.', 'The excerpt explains democratization as the transition to a more democratic political regime and describes it as complex, long-term, dynamic and open-ended.', 25),('0402d8c5-bdbc-4db8-8440-6692437fe4bc'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Define a political party based on the excerpt.', 'An organized group of individuals who share the same political ideologies, beliefs and interests and who seek to win elections and control state power and machinery of government.', 'The textbook defines political parties as organized groups sharing the same ideologies and seeking to win elections to control state power.', 26),('55b96d14-a85a-48ec-8508-cbaae1214de9'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'According to the textbook, what is an interest group?', 'An organization or group of people autonomous from government or political parties with the objective of influencing government and promoting members'' interests.', 'The excerpt defines interest groups as autonomous organizations aiming to influence government and promote the interests of their members.', 27),('66903692-e03e-4777-80c2-9e601dd47131'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Define the Independent National Electoral Commission as presented in the excerpt.', 'A corporate body charged with organizing, conducting and supervising elections into electoral offices in the country.', 'The excerpt defines the Independent National Electoral Commission as a corporate body responsible for organizing, conducting and supervising elections.', 28),('a6be1d56-a881-4c87-8702-54f69a8d190b'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'What is ''civic engagement'' according to the text?', 'The many ways people participate in civic, community, and political life—ranging from becoming informed, participating in public dialogue, volunteering, voting, community organizing to political advocacy, with commitment to improve one''s community.', 'The excerpt defines civic engagement as participation in civic and political life including being informed, dialogue, volunteering, voting and advocacy to improve community life.', 29),('5834daaf-b759-4902-8573-bd82158c99bc'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'List the three core values of democracy named in the excerpt.', 'Liberty (freedom), Justice, and Equality.', 'The excerpt names liberty/freedom, justice and equality as the three core values central to democracy.', 30),('6466b2f3-b9f0-4055-89ba-e3c3bb19a277'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Using the glossary in the excerpt, how can ''civic societies'' be understood?', 'As the ''third sector'' of society, distinct from government and business, including the family and the private sphere.', 'The glossary defines civic societies as the ''third sector'' distinct from government and business, including family and the private sphere.', 31),('531c0583-8cf1-466d-8068-9efee026bca9'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many functions of the Independent National Electoral Commission are listed in Table 1.1 of the excerpt?', '9', 'The excerpt lists nine functions of the Independent National Electoral Commission, numbered 1 through 9.', 32),('ee763fd3-44b4-4d5b-8990-57fb8f20a021'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many functions of political parties are enumerated in the excerpt?', '9', 'The textbook lists nine functions performed by political parties, numbered in the excerpt.', 33),('3a794527-1e3f-4075-846c-2b4fc4697e64'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many functions of pressure groups are listed in the excerpt?', '8', 'The excerpt presents eight functions of pressure groups, numbered 1 through 8.', 34),('343d6724-bf73-4bed-8f79-e17dafb01911'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many ways of social transformation are listed under lesson 1.4 (a–e)?', '5', 'Lesson 1.4 lists five manifestations of social transformation labeled a) through e).', 35),('d1d9e38d-cd7e-4cb1-8423-e1b57eca8bc5'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many core values of democracy are identified in the excerpt?', '3', 'The excerpt identifies three core values central to democracy: liberty, justice and equality.', 36),('1e05abce-4138-44d5-87e5-3e0532b13508'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'According to lesson 1.6, how many major aspects of democracy are described?', '3', 'Lesson 1.6 states democracy has three aspects: social, economic and political.', 37),('52bbfdc9-ff5e-4983-847a-70c4fd8f9a0a'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many key words are listed near the start of Unit 1?', '8', 'The excerpt lists eight key words at the start of the unit (Accountability, Democracy, Democratization, Federal government, Majority rule, Sovereignty, The rule of law, Tolerance).', 38),('e07aa497-e27d-44ec-8a3d-113f1342f5ea'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many lessons are contained in Unit 1 as listed in the excerpt?', '6', 'The excerpt lists six lessons under Unit 1, so the number of lessons is six.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('4bcd0c92-3508-43ba-8e20-48b50045aebd'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Demo'' and ''Kratos'' meaning people and rule', TRUE, 0),('3c4405a1-ac6d-4dad-8730-42378ed22b95'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Demos'' and ''Polis'' meaning people and city', FALSE, 1),('7a5b3b1a-65bb-45c2-85e8-e02af274f578'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Kratos'' and ''Nomos'' meaning rule and law', FALSE, 2),('b5fcae43-e1cb-47c5-8198-1bc3bdf8246a'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Demo'' and ''Nomos'' meaning people and law', FALSE, 3),('6a2099a4-94ae-4dab-812d-706c30327b9b'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A state of government in which people hold ruling power directly or indirectly through elected representatives', TRUE, 0),('c7549552-473b-49ca-813a-a483ec166142'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A system where rule is exercised exclusively by hereditary monarchs', FALSE, 1),('0a267185-6725-41a9-8e46-1e0dc434143a'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A political order where a single party permanently controls the state', FALSE, 2),('f8c2cbea-8f59-4983-8c10-5d5e1f3f45bf'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A society where decisions are made only by informal community elders', FALSE, 3),('5718cccd-89f1-4c39-861b-4951c0a541a2'::uuid, 'a105324a-e809-4965-8842-2cfa1ae58861'::uuid, 'Liberty (freedom), Justice, and Equality', TRUE, 0),('8aa4bc93-0bd6-4836-82b7-a452653539dc'::uuid, 'a105324a-e809-4965-8842-2cfa1ae58861'::uuid, 'Authority, Tradition, and Hierarchy', FALSE, 1),('6cc41b34-19b2-4dd9-8e25-8fc67feccf99'::uuid, 'a105324a-e809-4965-8842-2cfa1ae58861'::uuid, 'Wealth accumulation, Monopolies, and Status', FALSE, 2),('fb0c075b-4fd8-4b93-8b15-4bda33543659'::uuid, 'a105324a-e809-4965-8842-2cfa1ae58861'::uuid, 'Secrecy, Centralization, and Exclusion', FALSE, 3),('a5529e7a-7821-41da-8953-bf55f3caf8d6'::uuid, 'df768498-2b6e-4443-8a3f-7c6bca25d0ce'::uuid, 'An instantaneous replacement of one ruler with another', FALSE, 0),('4f1643ef-645a-44ea-8567-014e93dd8557'::uuid, 'df768498-2b6e-4443-8a3f-7c6bca25d0ce'::uuid, 'A complex, long-term, dynamic and open-ended process toward a more democratic political regime', TRUE, 1),('9d656c6b-f4be-4088-8005-2399a7a5a8d5'::uuid, 'df768498-2b6e-4443-8a3f-7c6bca25d0ce'::uuid, 'A strictly economic reform program with no political change', FALSE, 2),('ec7ee775-05f4-4e25-81f3-6d61fea608e6'::uuid, 'df768498-2b6e-4443-8a3f-7c6bca25d0ce'::uuid, 'A temporary experiment in local governance with fixed end date', FALSE, 3),('84c83eac-0b9a-485a-8f8e-95cfdc143f3a'::uuid, '875b5f28-1b05-462a-825d-014e85872228'::uuid, 'Political parties', TRUE, 0),('cbb18911-2d8a-4812-851c-da37da84271a'::uuid, '875b5f28-1b05-462a-825d-014e85872228'::uuid, 'Tectonic forces', FALSE, 1),('23334407-cf51-4dca-82da-71f4fa19f0ec'::uuid, '875b5f28-1b05-462a-825d-014e85872228'::uuid, 'Ocean currents', FALSE, 2),('95dbeac4-1c90-414f-819d-76638288d770'::uuid, '875b5f28-1b05-462a-825d-014e85872228'::uuid, 'Astrological signs', FALSE, 3),('fd81f95d-800b-4eaa-8659-80584150a6b6'::uuid, 'b8953843-d1c5-4004-89f4-80d0df4c851b'::uuid, 'Interest groups', FALSE, 0),('97e98937-de90-42b4-87fe-f6b6c50a1e2d'::uuid, 'b8953843-d1c5-4004-89f4-80d0df4c851b'::uuid, 'Civil societies', FALSE, 1),('7392618c-222d-4421-847e-e226f1639e1c'::uuid, 'b8953843-d1c5-4004-89f4-80d0df4c851b'::uuid, 'Political parties', FALSE, 2),('8555d791-adb9-4558-81a3-5ba584fcbd5c'::uuid, 'b8953843-d1c5-4004-89f4-80d0df4c851b'::uuid, 'Weather systems', TRUE, 3),('4c453a1d-21a2-422d-8c89-41ce50e845c4'::uuid, '58ceedaa-2016-4d40-83ed-56055aff5012'::uuid, 'They are instruments through which power is attained by means of free, fair and transparent elections', TRUE, 0),('31022821-ba3f-4ddf-889c-865e528a7999'::uuid, '58ceedaa-2016-4d40-83ed-56055aff5012'::uuid, 'They are permanent administrative branches of the civil service', FALSE, 1),('b9e8e4da-8743-4820-8906-6aca2ff6ce25'::uuid, '58ceedaa-2016-4d40-83ed-56055aff5012'::uuid, 'They are private clubs with no role in elections', FALSE, 2),('7516ff04-4bd2-4057-8d9e-d7ad8be00809'::uuid, '58ceedaa-2016-4d40-83ed-56055aff5012'::uuid, 'They are solely welfare providers with no political functions', FALSE, 3),('39754469-4841-48ca-8e93-d84d18a84c9c'::uuid, 'de1ff582-302b-4517-8716-063fbdb1e66d'::uuid, 'They differ in final goal but both contribute to consciousness raising and protection of rights', TRUE, 0),('3920609e-a67b-45c5-8688-14b9085effcf'::uuid, 'de1ff582-302b-4517-8716-063fbdb1e66d'::uuid, 'Civil societies are defined as branches of the government', FALSE, 1),('c949c306-9294-4823-8e9b-4d1dd866f509'::uuid, 'de1ff582-302b-4517-8716-063fbdb1e66d'::uuid, 'Civil societies are exactly the same as political parties', FALSE, 2),('7e463e70-ba46-4914-8a40-ae9f085e06d8'::uuid, 'de1ff582-302b-4517-8716-063fbdb1e66d'::uuid, 'Civil societies are international corporations', FALSE, 3),('8afe8bce-6bda-453a-8fa4-6ae3fe76824f'::uuid, '30edd166-638f-4abb-8818-8ce9cc9ac76d'::uuid, 'They act as transmission belts between people and government', TRUE, 0),('85c36e49-e07a-4823-82fd-01185712b378'::uuid, '30edd166-638f-4abb-8818-8ce9cc9ac76d'::uuid, 'They operate as the national electoral commission', FALSE, 1),('8b82eed3-cf74-435e-8a76-6a445316e235'::uuid, '30edd166-638f-4abb-8818-8ce9cc9ac76d'::uuid, 'They are identical to the judiciary', FALSE, 2),('f1b222dc-7e53-419c-815e-ee4b8172fa14'::uuid, '30edd166-638f-4abb-8818-8ce9cc9ac76d'::uuid, 'They must govern local communities directly', FALSE, 3),('64bb22cb-28ab-4b34-81b6-30c10c4c723a'::uuid, '33a61744-31b7-4fcc-8759-38d0bc7372b7'::uuid, 'Be free and independent with sufficient material and human resources', TRUE, 0),('44c13a5d-4b02-4370-86df-a9c6605102d9'::uuid, '33a61744-31b7-4fcc-8759-38d0bc7372b7'::uuid, 'Be tightly controlled by the state to ensure consistency', FALSE, 1),('2d00d155-d4b1-42e8-87eb-cf5c7b593e89'::uuid, '33a61744-31b7-4fcc-8759-38d0bc7372b7'::uuid, 'Operate only in urban areas', FALSE, 2),('ac478db5-3fe0-4645-805f-618004ce3f37'::uuid, '33a61744-31b7-4fcc-8759-38d0bc7372b7'::uuid, 'Provide entertainment only, not information', FALSE, 3),('a3f43af3-10fb-490f-8195-5d3c8a1f38f1'::uuid, 'a32bdb28-69b8-43a8-87d8-8fb7d950375f'::uuid, 'Registers voters', TRUE, 0),('7d43d437-749f-4b26-8b24-8fac55ff783a'::uuid, 'a32bdb28-69b8-43a8-87d8-8fb7d950375f'::uuid, 'Issues passports', FALSE, 1),('d9a6dfcc-b444-4440-8acb-2d24f65fe481'::uuid, 'a32bdb28-69b8-43a8-87d8-8fb7d950375f'::uuid, 'Manages national parks', FALSE, 2),('9de00057-ae69-46d2-8b53-a56fa00611e1'::uuid, 'a32bdb28-69b8-43a8-87d8-8fb7d950375f'::uuid, 'Conducts monetary policy', FALSE, 3),('05c94bb0-dcfe-4a6d-8408-ac5196eda729'::uuid, 'bfe36918-f29c-4824-8c1c-546854c4c1f4'::uuid, 'Provides security at the polling stations', TRUE, 0),('4623aa93-0250-4971-88a5-c8c4a2603240'::uuid, 'bfe36918-f29c-4824-8c1c-546854c4c1f4'::uuid, 'Issues driving licenses', FALSE, 1),('be072462-af62-445a-855e-177c14505089'::uuid, 'bfe36918-f29c-4824-8c1c-546854c4c1f4'::uuid, 'Grades school examinations', FALSE, 2),('10b794ad-c098-4b4e-88d3-16b14f895e9c'::uuid, 'bfe36918-f29c-4824-8c1c-546854c4c1f4'::uuid, 'Manages national healthcare services', FALSE, 3),('e724b782-188b-4a29-841c-26fe3338439a'::uuid, 'c19aee6e-bff6-4424-8285-415b33f059ac'::uuid, 'Serve as a forum for national unity and mutual understanding', TRUE, 0),('23ccc174-3578-4fe4-8705-46aa31e1f473'::uuid, 'c19aee6e-bff6-4424-8285-415b33f059ac'::uuid, 'Operate as a national police force', FALSE, 1),('cbfb261e-10cb-4ca3-8f29-f0046a65a2e1'::uuid, 'c19aee6e-bff6-4424-8285-415b33f059ac'::uuid, 'Collect taxes for the state', FALSE, 2),('de47e6cd-4533-40d3-88bb-7a9f4af9557e'::uuid, 'c19aee6e-bff6-4424-8285-415b33f059ac'::uuid, 'Control all private media outlets', FALSE, 3),('c2e0b7ac-0bd8-446c-807a-29b5c5ad61c4'::uuid, '6ab0080c-81ef-42da-8878-a68539f8471c'::uuid, 'Acts as a watchdog over public policies', TRUE, 0),('d4b77625-3bf5-4836-877b-26b7e6a96cb2'::uuid, '6ab0080c-81ef-42da-8878-a68539f8471c'::uuid, 'Directly conducts national elections', FALSE, 1),('da7b7910-d3a3-459e-8745-9dd239a2fcb4'::uuid, '6ab0080c-81ef-42da-8878-a68539f8471c'::uuid, 'Prints official currency', FALSE, 2),('3797bed3-49d7-4f45-81b3-62b20de35b82'::uuid, '6ab0080c-81ef-42da-8878-a68539f8471c'::uuid, 'Decides judicial cases', FALSE, 3),('dd5801a2-8f38-42d8-85e4-2451b22756d7'::uuid, '3e436b1b-ba5d-46ef-8d0d-803bee50fd26'::uuid, 'Procedural justice', TRUE, 0),('677065ca-df38-4931-8307-aba1f5bb3a28'::uuid, '3e436b1b-ba5d-46ef-8d0d-803bee50fd26'::uuid, 'Personal freedom from arbitrary arrest', FALSE, 1),('eac1dacd-770e-4378-80fb-fc65f0dfcd43'::uuid, '3e436b1b-ba5d-46ef-8d0d-803bee50fd26'::uuid, 'Political freedom to participate in elections', FALSE, 2),('32fc9fd6-d46d-4b51-81af-70947b41cf24'::uuid, '3e436b1b-ba5d-46ef-8d0d-803bee50fd26'::uuid, 'Economic freedom to acquire and use private property', FALSE, 3),('6674e4a0-b732-4d7a-87af-a72066155667'::uuid, '334c0d7c-cadb-4c41-86b5-c997ee00b2eb'::uuid, 'Distributive justice', TRUE, 0),('7d312991-3b1c-4ed2-89e5-f6e1042f6800'::uuid, '334c0d7c-cadb-4c41-86b5-c997ee00b2eb'::uuid, 'Absolute monarchy', FALSE, 1),('07a95eb0-d593-4b1e-81b7-349a90d4237f'::uuid, '334c0d7c-cadb-4c41-86b5-c997ee00b2eb'::uuid, 'Unaccountable rule', FALSE, 2),('078d0b16-8867-4d99-840b-d7e912cc9d4c'::uuid, '334c0d7c-cadb-4c41-86b5-c997ee00b2eb'::uuid, 'Economic monopolization', FALSE, 3),('5b70679d-4f00-4971-89fb-e0bb73e4027d'::uuid, 'bd39d45e-4ca7-4834-8c90-0538a65d7a36'::uuid, 'All adults have equal political rights (one person, one vote)', TRUE, 0),('32594b66-15a4-43fd-820c-9b547da60811'::uuid, 'bd39d45e-4ca7-4834-8c90-0538a65d7a36'::uuid, 'Only property owners may vote', FALSE, 1),('b2db0910-c03b-4695-8461-f9dd0a8390b3'::uuid, 'bd39d45e-4ca7-4834-8c90-0538a65d7a36'::uuid, 'Only hereditary leaders have political rights', FALSE, 2),('6d858a3d-5619-48cb-82dd-57df219ce52e'::uuid, 'bd39d45e-4ca7-4834-8c90-0538a65d7a36'::uuid, 'Political rights are given only to military officers', FALSE, 3),('651c0a59-689a-4134-8d11-c37dae43c59e'::uuid, 'f04fa500-1c71-4eb5-8bd5-f03d41700053'::uuid, 'Equitable and just distribution of wealth and resources and recognition of rights to work and fair wages', TRUE, 0),('1e8e098c-e2de-4d9e-8a10-db29f8df5d9d'::uuid, 'f04fa500-1c71-4eb5-8bd5-f03d41700053'::uuid, 'Strict state ownership of all industries with no private property', FALSE, 1),('c231f7d2-709b-43db-86e8-d41405e94115'::uuid, 'f04fa500-1c71-4eb5-8bd5-f03d41700053'::uuid, 'Complete absence of taxation', FALSE, 2),('c85084b0-3d73-4913-840e-ae52b1127532'::uuid, 'f04fa500-1c71-4eb5-8bd5-f03d41700053'::uuid, 'Political domination by a single family', FALSE, 3),('54ff49e0-b713-4e9b-8808-3af445e26aa3'::uuid, 'c3a53e01-73eb-48eb-8c41-bc4eb7a2456d'::uuid, 'Complex, long-term, dynamic and open-ended process', TRUE, 0),('8a07e9d4-948e-474d-8b38-4a02827316b2'::uuid, 'c3a53e01-73eb-48eb-8c41-bc4eb7a2456d'::uuid, 'A short and fixed-term program', FALSE, 1),('482e59d5-f542-4762-8b3d-6abe55c3de24'::uuid, 'c3a53e01-73eb-48eb-8c41-bc4eb7a2456d'::uuid, 'A mechanical administrative change only', FALSE, 2),('ad8b3f9f-5e67-42fc-864a-e98dcb9ed7a3'::uuid, 'c3a53e01-73eb-48eb-8c41-bc4eb7a2456d'::uuid, 'A purely economic transformation', FALSE, 3),('83bd0c51-da0f-41de-8bec-dc2aaea5735b'::uuid, '857cdc90-df04-4676-88d7-e2224f0efd9d'::uuid, 'Six', TRUE, 0),('64250a10-96fc-4160-8faf-8bd484859bab'::uuid, '857cdc90-df04-4676-88d7-e2224f0efd9d'::uuid, 'Four', FALSE, 1),('c6e4e8d2-9909-45e0-853d-1e1a4337ad86'::uuid, '857cdc90-df04-4676-88d7-e2224f0efd9d'::uuid, 'Ten', FALSE, 2),('60095082-3905-4fd0-801b-97e5faba569a'::uuid, '857cdc90-df04-4676-88d7-e2224f0efd9d'::uuid, 'Two', FALSE, 3),('0bd86428-77ec-403c-8bc1-e8de2657e8fa'::uuid, '9a0141a0-dd9e-4b96-830c-f41f1a60bc4f'::uuid, 'True', TRUE, 0),('4826b74a-e581-42de-8910-08223069729c'::uuid, '9a0141a0-dd9e-4b96-830c-f41f1a60bc4f'::uuid, 'False', FALSE, 1),('70f18a38-f8a1-40db-813b-54294408fe6d'::uuid, 'deadc2e6-9b04-4ef5-837a-fa67e0dbcbc3'::uuid, 'True', TRUE, 0),('41bf7d2b-30d8-4431-8dfe-97d64d6c0f59'::uuid, 'deadc2e6-9b04-4ef5-837a-fa67e0dbcbc3'::uuid, 'False', FALSE, 1),('b47a4180-deff-434d-8c77-30f5846b4190'::uuid, '7394367f-94b7-4f81-8031-f6fc5d475fe1'::uuid, 'True', FALSE, 0),('3999de53-9806-4538-8f0b-a825994177ed'::uuid, '7394367f-94b7-4f81-8031-f6fc5d475fe1'::uuid, 'False', TRUE, 1),('e601880d-ffd9-4cdc-8a5f-a7db3928bf55'::uuid, 'ede66253-225c-4e2a-8b4b-ea19833ae585'::uuid, 'True', TRUE, 0),('522bc4a2-54fe-4fce-8bdd-4fdcd2f154ec'::uuid, 'ede66253-225c-4e2a-8b4b-ea19833ae585'::uuid, 'False', FALSE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'Citizenship', 'Unit 2', 'Molarum Grade 10 — Citizenship Unit 2: Citizens in the Digital Technology Age', 'Source-grounded Molarum Grade 10 Citizenship questions for Unit 2: Citizens in the Digital Technology Age.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('a37f6a19-bd05-4d25-8e4d-f1131f6be5e1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which one of the following is not included under the principles of democratic system?', 'The existence of one-party system', 'The excerpt lists popular sovereignty, accountability and transparency, and universal suffrage as democratic principles and contrasts these with one-party systems, which are not democratic principles.', 0),('017dd4d2-1425-4304-86f4-1f1356a79674'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is listed as a key word for Unit 2?', 'Digital citizenship', 'The key words section of the unit explicitly lists ''Digital citizenship'' as a key word for Unit 2.', 1),('7cbdc389-89c5-4edd-8d7b-2596f3085db7'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'How many lessons are listed under Unit 2 in the introduction?', 'Four', 'The unit lists four lessons: Implications of digital technology on citizens; The ethics of using digital technology; Opportunities of digital technology for young citizens; and The impacts of unethical use of digital technology on young citizens.', 2),('38cfbe3d-9a8d-4d80-8f4f-adcda6ffc8a5'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is presented as a positive implication of digital technology on emotions?', 'Self-control', 'The excerpt lists self-control as a positive effect of digital technology on citizens'' emotions, while isolation, anonymity, and depression are described as negative implications.', 3),('110a45d4-5d96-47fc-84fb-c32250e271c1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which statement about excessive digital technology use is supported by the excerpt?', 'Excessive use typically leads to negative effects', 'The excerpt states that moderate use produces positive effects whereas excessive, obsessive, or addictive use typically leads to negative effects on emotions.', 4),('e9530dcb-1da0-4370-8e39-808774d0c9c6'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which example in the excerpt illustrates how digital technology fosters socialization?', 'Mobile phones enable people to stay closer to loved ones across distances', 'The excerpt explains that digital technologies allow people to stay closer to loved ones when physically far apart, which fosters socialization; other options are unsupported or contradicted by the text.', 5),('405c28e0-88ad-443e-85df-ac7fd6ce0077'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'According to the excerpt, which role can digital technology play in emotion regulation?', 'It gives access to health and wellness resources to build skills like mindfulness', 'The excerpt states that technology provides access to health and wellness resources and can teach skills such as gratitude, mindfulness, and emotion regulation.', 6),('a32337e0-078f-4960-8e31-4454a2357adb'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is described as a form of ''secondhand living''?', 'Creating imaginary identities and spending hours in virtual worlds', 'Secondhand living is described as people creating imaginary identities in virtual worlds and becoming preoccupied with virtual realities instead of firsthand life.', 7),('3daa3c5a-cb20-4193-8aeb-c20f1884f755'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which reason does the excerpt give for why websites and games encourage prolonged use?', 'They want users to interact so they can bring in advertising money', 'The excerpt explains that websites and games are designed to keep users interacting because this interaction brings in advertising revenue or encourages purchases, which can lead to addiction.', 8),('cd0d56d8-97c9-4a49-8e4d-c333bc6d6758'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is NOT listed as a positive implication of digital technology on social life in the excerpt?', 'Creating social alienation', 'Speedy communication, promoting economic growth, and improving health care are listed as positive implications, whereas social alienation is listed among negative social impacts.', 9),('e809d382-915c-4d5b-8a2b-b66c207cfd3e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'How has digitalization changed banking and finance according to the excerpt?', 'Online banking can be done via laptop, tablet, or phone and helps arrange transfers and payments', 'The excerpt states that online banking is performed via laptops, tablets, or phones and users can remotely check payments and arrange transfers and bill payments.', 10),('e362621b-1820-45dd-8091-e72a7ce5929e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which benefit of digital technology to health care is mentioned in the excerpt?', 'Patients can access diagnostic tools and keep track of appointments via handheld devices', 'The excerpt notes that patients have access to diagnostic tools and can use applications to manage appointments and medication reminders via handheld devices.', 11),('0fd755e4-778b-4b5d-8c09-9c7654a8f743'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which negative social effect does the excerpt link to lack of real-life contact?', 'Social alienation', 'The excerpt explains that increased reliance on digital devices for interaction can lead to social alienation due to reduced real-life contact.', 12),('86a75f1e-5b69-4555-8cca-46cd2cbdd527'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which example from the excerpt illustrates erosion of privacy?', 'Employers searching for people online and finding unflattering photographs', 'The excerpt gives the example that employers can search online and find unflattering photos or controversial opinions, demonstrating erosion of privacy.', 13),('3ffcbf5a-ef8a-4c5c-824c-0f72c52c4210'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'What cause of job insecurity is described in the excerpt?', 'Computers replacing human tasks and remote work enabling undercutting of wages', 'The excerpt states that computers replace many tasks and remote work allows workers in low-wage economies to undercut others, causing job insecurity.', 14),('04d74193-2c89-471c-8c36-18043aa93efa'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which risk of data insecurity is mentioned in the excerpt?', 'A single breach can expose vast amounts of private information', 'The excerpt warns that huge amounts of private information are stored digitally and a single breach can put this data into the hands of criminals or other harmful entities.', 15),('642bd23a-32fe-4f68-8193-f9f6a16ac362'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'How does the excerpt describe the internet''s role in crime and terrorism?', 'A fertile ground for malevolent forces to operate internationally and on vast scales', 'The excerpt states the internet is fertile ground for malevolent forces such as terrorists and drug dealers to operate internationally and at scale.', 16),('90d7b6ce-64c5-4aaf-8ba3-42f8c0714347'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which physical health issue is linked to prolonged use of digital devices in the excerpt?', 'Eyestrain and blurred vision', 'The excerpt notes that prolonged attention to digital devices can cause digital eyestrain, with symptoms like blurred vision and dry eyes.', 17),('a9bbae25-d0c4-48c0-8f8f-7a121d7c5b91'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is listed as an ethical code/principle in using digital technology?', 'Etiquette', 'The excerpt lists etiquette as one of the ethical codes guiding appropriate behaviour when using digital technology.', 18),('7b04dec1-ceef-4bc2-8a58-9765ebe390f6'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which behaviour is given as an example of inappropriate responsibility in the excerpt?', 'Students copy materials from the internet without giving credit', 'The excerpt explicitly cites students copying internet materials for class projects without crediting the author as an example of inappropriate responsibility.', 19),('a368e950-9e1a-43f6-8444-0fdb434c9bce'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'The excerpt states that protecting one’s equipment is only a matter of personal responsibility and has no relevance to community safety.', 'False', 'The excerpt explains that protecting one’s equipment is both personal responsibility and necessary for protecting the community, so the statement is false.', 20),('4d78cd3d-f77d-43e4-8b59-ea8b8d0937e8'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'According to the excerpt, telling your email or social media passwords to others is an example of inappropriate confidentiality.', 'True', 'The excerpt lists sharing email, Facebook, and other passwords as an example of inappropriate confidentiality, so the statement is true.', 21),('6c489d06-5e00-48ae-8d3a-b3c0e3eb78ac'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'The excerpt claims there is an agency that guarantees truth and accuracy of all internet information.', 'False', 'The excerpt states there is no agency monitoring truth or accuracy of information on the internet, so the claim is false.', 22),('d0621c52-718f-4949-8c0a-b674f855431e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'The excerpt asserts that developing digital citizenship for children and young people has been a priority in many countries.', 'True', 'The excerpt states that developing digital citizenship and ensuring children are active and respectful online users has been a priority in countries around the world.', 23),('6ecd7ec7-2627-4458-8a6c-1d797425ba6e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Briefly explain how digital technology provides information access for young citizens as described in the excerpt.', 'The excerpt explains digital technology gives open access to information about local and global events, enabling young citizens to engage collaboratively and be part of world conversations.', 'The unit states that digital technology is a window to information about one’s country and the world, which helps young people participate and collaborate globally.', 24),('d226440b-30d5-4c26-8e56-29eae14edbd1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'What learning opportunities does the excerpt say digital technology offers?', 'It allows access to a huge portion of the world’s knowledge, virtual delivery of lessons and courses, direct learning from sources, short-term trainings, and skill development via videos and audios.', 'The excerpt lists virtual lessons, access to global knowledge, short trainings, and multimedia resources as ways digital technology advances learning.', 25),('ebdd2f1b-f23f-49d9-8aaf-6b69c75e6993'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How does the excerpt describe versatile working opportunities created by digital technology for young people?', 'The excerpt notes increased connectivity allows remote work from home and easier searching and applying for online job opportunities, expanding work options for young people.', 'The unit explains that many jobs can be done remotely and digital tools enable young people to find and apply for work online, creating versatile work opportunities.', 26),('ace0e3cb-94df-4938-85ce-07e0e87634ef'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'According to the excerpt, why is digital technology fertile ground for innovation and creativity among the young?', 'Because access to information, connectivity, and digital learning exposes young people to new ideas and technologies that enable creativity and innovation.', 'The excerpt states that information access and connectivity provide enabling factors for exposure to new ideas, promoting creativity and innovation among young citizens.', 27),('428ce212-71f1-40be-8b29-dd79a2eb923a'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Define ''plagiarism'' as given in the excerpt.', 'Plagiarism is presenting the ideas, words, or other intellectual property of other persons as one’s own without credit.', 'The excerpt defines plagiarism as using someone else’s work or ideas and presenting them as your own, which is an unethical academic practice.', 28),('74e973a5-bc55-478a-8557-075418b08a19'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'What is digital media piracy according to the excerpt?', 'Digital media piracy is the illegal circulation and distribution of music, movies, books and other copyrighted content through digital technologies without permission.', 'The excerpt describes piracy as unauthorized distribution of copyrighted material online, violating property rights and harming production industries.', 29),('0f6afd17-f7c5-4d8d-87ce-35a5a3c63ec4'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'What negative effect does the excerpt associate with sharing suggestive videos among young people?', 'The excerpt links sharing suggestive videos to early sexual experiences, addiction to what is watched, relationship separation, and wider problems in education and family life.', 'The text explains that sharing and watching suggestive videos can lead to early sexual behaviour, addiction, and negative impacts on education and family relationships.', 30),('34e8013b-9d02-4bb6-8d29-8624b5466278'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Explain what an ''ethical dilemma'' means as defined in the glossary of the excerpt.', 'An ethical dilemma is a decision-making problem with two possible options where neither is absolutely acceptable from an ethical perspective.', 'The glossary defines ethical dilemma as facing two options, neither of which is fully acceptable ethically, illustrating moral conflict.', 31),('279e538c-9694-4aee-8391-ab8523ce617d'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many lessons are numbered under Unit 2 in the unit introduction?', '4', 'The unit introduction lists four lessons numbered 1 to 4 under Unit 2.', 32),('356e0128-bcdf-4eed-881c-3a72530740bc'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many key words are listed at the start of Unit 2?', '4', 'The key words section lists Digital citizenship, Digital ethics, Digital technology, and Ethical dilemma, a total of four key words.', 33),('48f842cc-a657-4e3a-857f-9c736815f5c1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many ethical codes/principles (named headings) are described in Lesson 2.2 (Etiquette through Accuracy/trustworthiness)?', '6', 'Lesson 2.2 lists six ethical codes by heading: Etiquette, Responsibility, Safety, Security, Confidentiality, and Accuracy/trustworthiness.', 34),('cf15a80c-946d-4b1c-8585-44bcbb6aa4b8'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Count the number of positive implications of digital technology on citizens'' emotions that are listed by heading (from Self-control to Increased emotional satisfaction).', '7', 'The excerpt lists seven positive emotional implications by heading: Self-control; Fostering socialization; Maintaining emotional balance; Supporting happiness and wellbeing; Regulating emotions; Providing a sense of security; Increased emotional satisfaction.', 35),('a3b7815d-2009-497f-8d14-921385a22476'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many negative implications of digital technology on the social life are explicitly listed (Social alienation through Effects on physical health)?', '6', 'The excerpt discusses six negative social impacts: Social alienation, Eroding privacy, Job insecurity, Data insecurity, Aggravate crime and terrorism, and Effects on physical health.', 36),('fcb1d3ed-8182-4de4-8ee7-6417fed7b1b8'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many specific opportunities of digital technology for young citizens are listed in Lesson 2.3 (Information access through Innovation and creative opportunities)?', '5', 'Lesson 2.3 lists five opportunities: Information access; Social connectivity; Learning opportunities; Versatile working opportunities; and Innovation and creative opportunities.', 37),('3f5ab752-1d7f-4fef-8451-474a7c53ef8a'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many specific impacts of unethical use of digital technology on young citizens are listed at the start of Lesson 2.4 (Academic dishonesty through Identity theft and Unfriendly and revenge sex)?', '4', 'The excerpt lists four impacts under that heading: Academic dishonesty, Digital media piracy, Identity theft, and Unfriendly and revenge sex.', 38),('5b2fcad4-ff9f-485d-84f7-8ca62760f656'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many glossary entries are shown at the end of the excerpt (from Cyber security to Plagiarism)?', '11', 'The glossary provides eleven entries starting with Cyber security and ending with Plagiarism as listed in the excerpt.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
